import { host } from "host";

async function main(): Promise<void> {
  await host.chat.broadcast("Zombies are incoming!");

  const status = await host.server.status();
  const { x, y, z } = status.demoLocation;

  await Promise.all([
    host.world.spawnEntity({ type: "ZOMBIE", x: x + 1, y, z }),
    host.world.spawnEntity({ type: "ZOMBIE", x: x - 1, y, z }),
    host.world.spawnEntity({ type: "ZOMBIE", x, y, z: z + 1 })
  ]);

  const target = "GoldennBullet";
  const result = await host.player.sendMessage(target, "Invasion started: 3 zombies spawned near demo location.");
  if (!result.accepted || result.error) {
    console.log(`Could not deliver private message to ${target}. The player may be offline or unavailable: ${result.error ?? "Delivery not accepted"}`);
  }
}

main().catch((err) => {
  console.error("Script execution failed:", err);
});

